WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id),
course_frame AS (SELECT a.school_uid,a.course_id,a.category_id,COUNT(DISTINCT l.class_id) AS opened_n FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN ended_lessons l ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id WHERE a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id), pe AS (SELECT school_uid,course_id,category_id,activity_id,uid,MIN(CASE WHEN action='handin_homework' THEN event_time END) AS first_submit,MAX(CASE WHEN action='handin_homework' THEN event_time END) AS last_submit,MIN(CASE WHEN action='readover_homework_st' THEN event_time END) AS first_review,MAX(CASE WHEN action='readover_homework_st' THEN event_time END) AS last_review FROM eo_pdviews.dwd_acitive_user_lms_action_details_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND event_time>=1788537600 AND event_time<1789142400 AND role='student' AND biz_type=2 AND action IN ('handin_homework','readover_homework_st') GROUP BY school_uid,course_id,category_id,activity_id,uid) SELECT COUNT(1) AS submitted_pair_n,SUM(CASE WHEN e.last_review>=e.first_submit THEN 1 ELSE 0 END) AS subsequent_review_pair_n,SUM(CASE WHEN e.last_review>=e.last_submit THEN 1 ELSE 0 END) AS review_after_last_submit_pair_n,SUM(CASE WHEN e.last_review IS NULL THEN 1 ELSE 0 END) AS no_same_week_review_pair_n,SUM(CASE WHEN e.last_review<e.first_submit THEN 1 ELSE 0 END) AS review_only_before_submit_pair_n FROM pe e JOIN course_frame f ON e.school_uid=f.school_uid AND e.course_id=f.course_id AND e.category_id=f.category_id JOIN eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a ON a.id=e.activity_id AND a.school_uid=e.school_uid AND a.course_id=e.course_id AND a.category_id=e.category_id WHERE a.dt='2026-09-11' AND a.publish_flag=2 AND a.is_deleted=0 AND a.biz_type=2 AND a.start_time<1789142400 AND e.first_submit IS NOT NULL
